function simulateCacheEviction(operations, capacity, policy = 'allkeys-lru') {
  const store = new Map();
  let evictions = 0;
  let now = 1000;

  for (const op of operations) {
    now += 10;
    if (op.type === 'SET') {
      if (!store.has(op.key) && store.size >= capacity) {
        let candidateKey = null;
        if (policy === 'allkeys-lru') {
          let oldestAccess = Infinity;
          for (const [k, meta] of store.entries()) {
            if (meta.lastAccess < oldestAccess) {
              oldestAccess = meta.lastAccess;
              candidateKey = k;
            }
          }
        } else if (policy === 'allkeys-lfu') {
          let minCount = Infinity;
          for (const [k, meta] of store.entries()) {
            if (meta.accessCount < minCount) {
              minCount = meta.accessCount;
              candidateKey = k;
            }
          }
        }
        if (candidateKey) {
          store.delete(candidateKey);
          evictions++;
        }
      }
      store.set(op.key, {
        value: op.value,
        accessCount: 1,
        lastAccess: now
      });
    } else if (op.type === 'GET') {
      if (store.has(op.key)) {
        const item = store.get(op.key);
        item.accessCount++;
        item.lastAccess = now;
      }
    }
  }

  return {
    remainingKeys: Array.from(store.keys()),
    totalEvictions: evictions,
    capacity,
    policy
  };
}

